"""Migration of the Meridian CRM credit-hold sweep."""

from decimal import Decimal, InvalidOperation
from numbers import Number


def _decimal(value: object) -> Decimal:
    """Convert legacy numeric values, treating missing or empty values as zero."""
    if value is None:
        return Decimal(0)
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Decimal(0)
    try:
        # str(float) avoids importing binary floating-point artifacts into
        # threshold comparisons.
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _account_sort_key(account: dict) -> tuple[int, object]:
    """Provide deterministic primary-key ordering for typical account ID values."""
    acct_id = account.get("ACCT_ID")

    if isinstance(acct_id, str):
        return (1, acct_id)
    if isinstance(acct_id, Number):
        return (0, _decimal(acct_id))
    if acct_id is None:
        return (2, "")
    return (3, str(acct_id))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """Apply the nightly credit-hold sweep without mutating input rows."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, object]] = []

    eligible_indexes = [
        index
        for index, account in enumerate(accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indexes.sort(key=lambda index: _account_sort_key(accounts[index]))

    for index in eligible_indexes:
        source_account = accounts[index]
        account = new_accounts[index]
        acct_id = source_account.get("ACCT_ID")

        exposure = Decimal(0)
        for order in orders:
            if (
                order.get("ACCT_ID") == acct_id
                and order.get("DEL_FLG") != "Y"
                and order.get("STAT_CD") == "I"
            ):
                exposure += _decimal(order.get("TOT_AMT"))

        credit_limit = _decimal(source_account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * Decimal(8) / Decimal(10) and account.get("CRED_HOLD") == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
